import numpy as np
def fit(n,deg=4,basis='poly'):
    if basis=='poly':
        T=[t**k for k in range(deg+1)]
    else:
        T=[t**k for k in range(deg+1)]+[np.exp(-t)*t**0]
    T=np.column_stack(T)
    X=np.hstack([T, T*(A**n)[:,None]])
    c,_,_,_=np.linalg.lstsq(X,dA_dt,rcond=None)
    r=X@c-dA_dt
    return np.mean(r**2)/np.var(dA_dt), c
