import numpy as np
def basis_t(tt, kind):
    cols=[np.ones_like(tt)]
    if 'inv' in kind: cols.append(1/tt)
    if 'exp2' in kind: cols.append(np.exp(-2*tt))
    if 'exp1' in kind: cols.append(np.exp(-tt))
    if 'lin' in kind: cols.append(tt)
    if 'sq' in kind: cols.append(tt**2)
    return np.column_stack(cols)
